begin;
select no_plan();
select ok((select bool_and(c.relrowsecurity and not has_table_privilege('authenticated',c.oid,'select')) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('platform_playback_estimates','platform_retention_jobs','platform_storage_deletion_jobs','platform_resource_notices','platform_billing_operations')),'new lifecycle ledgers have RLS and no browser grants');
do $$ declare actor uuid:='92000000-0000-4000-8000-000000000001'; org uuid:='92000000-0000-4000-8000-000000000002'; begin
 insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data) values(actor,'authenticated','authenticated','lifecycle@synthetic.invalid','{}','{}'),('92000000-0000-4000-8000-000000000011','authenticated','authenticated','lifecycle-b@synthetic.invalid','{}','{}');
 insert into public.organizations(id,name,slug,owner_id) values(org,'Lifecycle synthetic','lifecycle-synthetic',actor),('92000000-0000-4000-8000-000000000012','Other school','lifecycle-other','92000000-0000-4000-8000-000000000011');
 insert into public.organization_admins(organization_id,user_id,role) values(org,actor,'owner');
 insert into public.organization_billing(organization_id,access_mode,platform_subscription_status) values(org,'standard','canceled'),('92000000-0000-4000-8000-000000000012','standard','canceled');
 insert into public.courses(id,organization_id,title,description,price,status) values('92000000-0000-4000-8000-000000000003',org,'Lifecycle','Synthetic',0,'published');
 insert into public.lessons(id,course_id,title,order_index) values('92000000-0000-4000-8000-000000000004','92000000-0000-4000-8000-000000000003','Synthetic',0);
end $$;
select ok(public.start_platform_trial('92000000-0000-4000-8000-000000000002','{"version":"2026-10-01","planKey":"trial"}'),'trial starts');
select is((select quota_mode from public.organization_billing where organization_id='92000000-0000-4000-8000-000000000002'),'enforce','new trials enforce without a manual update');
create temp table admitted as select public.admit_platform_playback('92000000-0000-4000-8000-000000000002','92000000-0000-4000-8000-000000000001','92000000-0000-4000-8000-000000000005',null,44100) as payload;
select ok((select (payload->>'allowed')::boolean from admitted),'long video session admitted');
select is((select extract(epoch from(expires_at-created_at))::integer from public.platform_playback_sessions where id=(select (payload->>'sessionId')::uuid from admitted)),44100,'12 hours plus 15 minutes remains bounded');
select ok(not public.record_platform_playback_estimate((select (payload->>'sessionId')::uuid from admitted),'92000000-0000-4000-8000-000000000011',30),'another user cannot report the session');
update public.platform_playback_sessions set created_at=now()-interval '2 minutes' where id=(select (payload->>'sessionId')::uuid from admitted);
select ok(public.record_platform_playback_estimate((select (payload->>'sessionId')::uuid from admitted),'92000000-0000-4000-8000-000000000001',60),'valid estimate accepted');
select public.record_platform_playback_estimate((select (payload->>'sessionId')::uuid from admitted),'92000000-0000-4000-8000-000000000001',60);
select is((select sum(estimated_seconds)::integer from public.platform_playback_estimates where organization_id='92000000-0000-4000-8000-000000000002'),60,'repeated heartbeat cannot exceed elapsed wall time');
update public.platform_capacity_cycles set base_used_seconds=18000 where organization_id='92000000-0000-4000-8000-000000000002';
select ok((public.admit_platform_playback('92000000-0000-4000-8000-000000000002','92000000-0000-4000-8000-000000000001','92000000-0000-4000-8000-000000000005',(select (payload->>'sessionId')::uuid from admitted),44100)->>'allowed')::boolean,'exhaustion preserves the existing session');
select ok(not (public.admit_platform_playback('92000000-0000-4000-8000-000000000002','92000000-0000-4000-8000-000000000001','92000000-0000-4000-8000-000000000005',null,44100)->>'allowed')::boolean,'exhaustion blocks a new bounded session');
select ok(not (public.admit_platform_playback('92000000-0000-4000-8000-000000000012','92000000-0000-4000-8000-000000000001','92000000-0000-4000-8000-000000000005',(select (payload->>'sessionId')::uuid from admitted),44100)->>'allowed')::boolean,'school B cannot reuse school A session');
select public.enqueue_platform_resource_notices('92000000-0000-4000-8000-000000000002');
select public.enqueue_platform_resource_notices('92000000-0000-4000-8000-000000000002');
select is((select count(*)::integer from public.platform_resource_notices where organization_id='92000000-0000-4000-8000-000000000002' and resource='delivery'),2,'70 and 90 percent notices are idempotent');
select public.reconcile_platform_retention('92000000-0000-4000-8000-000000000002');
select is((select count(*)::integer from public.platform_retention_jobs where organization_id='92000000-0000-4000-8000-000000000002'),0,'a live trial never starts deletion');
update public.organization_billing set access_expires_at=now()-interval '31 days' where organization_id='92000000-0000-4000-8000-000000000002';
select public.reconcile_platform_retention('92000000-0000-4000-8000-000000000002');
select is((select extract(epoch from(delete_after-ended_at))::integer from public.platform_retention_jobs where organization_id='92000000-0000-4000-8000-000000000002'),2592000,'retention is exactly 30 days after effective expiry');
select is(public.execute_platform_retention('92000000-0000-4000-8000-000000000012',null,true),'job_missing','missing job cannot delete');
select is(public.execute_platform_retention('92000000-0000-4000-8000-000000000002',null,false),'disabled','retention execution defaults off');
select public.claim_platform_retention_jobs(5);
select is(public.execute_platform_retention('92000000-0000-4000-8000-000000000002',now()-interval '1 second',true),'lease_lost','stale lease cannot delete');
update public.organization_billing set platform_subscription_status='active' where organization_id='92000000-0000-4000-8000-000000000002';
select is(public.execute_platform_retention('92000000-0000-4000-8000-000000000002',(select lease_until from public.platform_retention_jobs where organization_id='92000000-0000-4000-8000-000000000002'),true),'restored','restoration wins before final deletion');
select is((select count(*)::integer from public.lessons where id='92000000-0000-4000-8000-000000000004'),1,'restoration preserves teaching content');
update public.organization_billing set platform_subscription_status='canceled' where organization_id='92000000-0000-4000-8000-000000000002';
select public.reconcile_platform_retention('92000000-0000-4000-8000-000000000002');
select public.claim_platform_retention_jobs(5);
select is(public.execute_platform_retention('92000000-0000-4000-8000-000000000002',(select lease_until from public.platform_retention_jobs where organization_id='92000000-0000-4000-8000-000000000002'),true),'completed','synthetic deletion completes');
select is(public.execute_platform_retention('92000000-0000-4000-8000-000000000002',null,true),'completed','deletion is idempotent');
select is((select count(*)::integer from public.courses where id='92000000-0000-4000-8000-000000000003'),1,'course identities needed for purchases survive');
select is((select count(*)::integer from public.lessons where id='92000000-0000-4000-8000-000000000004'),0,'only expired synthetic teaching data removed');
select is((select count(*)::integer from public.organization_billing where organization_id='92000000-0000-4000-8000-000000000012' and retention_policy_version is null),1,'legacy school is not enrolled in retention');
select * from finish();
rollback;
